import{_ as t,o as s,c as e,ai as l}from"./chunks/framework.BI5prboT.js";const k=JSON.parse('{"title":"Rule（规则）","description":"","frontmatter":{},"headers":[],"relativePath":"AI/rule.md","filePath":"AI/rule.md"}'),i={name:"AI/rule.md"};function d(n,a,r,o,h,p){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="rule-规则" tabindex="-1">Rule（规则） <a class="header-anchor" href="#rule-规则" aria-label="Permalink to &quot;Rule（规则）&quot;">​</a></h1><p>Rule 是给 Agent 的<strong>短约束</strong>：始终要遵守，或改某类文件时要遵守。它不是流程手册，也不是外部工具。</p><p>和 Skill、MCP 的对照见：<a href="./skill-vs-mcp.html">Skill、MCP、Rule 异同</a>。项目级说明书见：<a href="./agents-md.html">AGENTS.md</a>。</p><h2 id="它干什么" tabindex="-1">它干什么 <a class="header-anchor" href="#它干什么" aria-label="Permalink to &quot;它干什么&quot;">​</a></h2><p>写进 Rule 的内容，Host 会<strong>按规则塞进上下文</strong>（常驻，或按文件 glob）。模型还没开始办事，就已经看见这些句子。</p><p>适合：</p><ul><li>禁令：禁止 <code>rm -rf</code>、禁止提交 <code>.env</code>、禁止用 flex <code>gap</code></li><li>某类文件的死规定：<code>*.scss</code> 里怎么写颜色、组件怎么命名</li><li>一两屏能说完的团队习惯</li></ul><p>不适合：</p><ul><li>几十步排障清单（会每条消息都占窗口）→ 用 <a href="./skill.html">Skill</a></li><li>查 Sentry、发 GitHub 评论 → 用 <a href="./mcp.html">MCP</a></li></ul><h2 id="文件长什么样" tabindex="-1">文件长什么样 <a class="header-anchor" href="#文件长什么样" aria-label="Permalink to &quot;文件长什么样&quot;">​</a></h2><p>Cursor 项目规则放 <code>.cursor/rules/</code>，一个规则一个 <code>.mdc</code>：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Taro 样式兼容</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">globs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.{scss,css}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alwaysApply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">禁止使用 flex gap。间距用 margin。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">禁止使用 dvh / svh / lvh，用 vh。</span></span></code></pre></div><table tabindex="0"><thead><tr><th>头字段</th><th>作用</th></tr></thead><tbody><tr><td><code>alwaysApply: true</code></td><td>每次对话都带上全文</td></tr><tr><td><code>globs</code></td><td>正在改的文件匹配时才带上</td></tr><tr><td><code>description</code></td><td>给 Agent 判断「要不要看这条」；不要 <code>alwaysApply</code> 时尤其有用</td></tr></tbody></table><p>用户规则在 Cursor 设置里，对所有项目生效。旧的单文件 <code>.cursorrules</code> 还能用，新项目优先拆成 <code>.cursor/rules/*.mdc</code>。</p><h2 id="和-skill-差在加载" tabindex="-1">和 Skill 差在加载 <a class="header-anchor" href="#和-skill-差在加载" aria-label="Permalink to &quot;和 Skill 差在加载&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Rule</th><th>Skill</th></tr></thead><tbody><tr><td>进上下文</td><td>常驻或 glob，<strong>全文进去</strong></td><td>先只放 <code>name</code> + <code>description</code>，对上了才读正文</td></tr><tr><td>写长了</td><td>每条消息都烧 token</td><td>没触发时几乎不占窗口</td></tr><tr><td>典型长度</td><td>几条到一两屏</td><td>可以带脚本、参考资料</td></tr></tbody></table><p>所以：<code>alwaysApply</code> 的 Rule 只放真正「每次都不能忘」的话。排障、发布检查做成 Skill。</p><h2 id="怎么写才有用" tabindex="-1">怎么写才有用 <a class="header-anchor" href="#怎么写才有用" aria-label="Permalink to &quot;怎么写才有用&quot;">​</a></h2><ul><li>写<strong>可执行的禁令 / 做法</strong>，不要写「注意代码质量」</li><li>一条 Rule 管一件事，用 glob 限制范围</li><li>和用户当轮对话、<a href="./agents-md.html">AGENTS.md</a> 打架时，以用户和项目说明书为准</li></ul>`,19)])])}const u=t(i,[["render",d]]);export{k as __pageData,u as default};
